/// The path of an icon, for `svg().path(…)`.
pub fn icon(name: &str) -> SharedString {
    SharedString::from(format!("icons/{name}.svg"))
}

/// Serves the icons to GPUI.
pub struct Icons;

impl AssetSource for Icons {
    fn load(&self, path: &str) -> Result<Option<Cow<'static, [u8]>>> {
        let name = path.trim_start_matches("icons/").trim_end_matches(".svg");
        Ok(ICONS.iter().find(|(n, _)| *n == name).map(|(_, svg)| Cow::Borrowed(svg.as_bytes())))
    }

    fn list(&self, path: &str) -> Result<Vec<SharedString>> {
        Ok(ICONS.iter().map(|(n, _)| icon(n)).filter(|p| p.starts_with(path)).collect())
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_icon_draws_something() {
        use resvg::{tiny_skia, usvg};
        for (name, svg) in ICONS {
            let tree = usvg::Tree::from_str(svg, &usvg::Options::default()).unwrap_or_else(|e| panic!("{name}: {e}"));
            let mut pixmap = tiny_skia::Pixmap::new(48, 48).unwrap();
            resvg::render(&tree, tiny_skia::Transform::from_scale(2.0, 2.0), &mut pixmap.as_mut());
            let inked = pixmap.pixels().iter().filter(|p| p.alpha() > 0).count();
            assert!(inked > 20, "{name} draws {inked} pixels");
        }
        assert!(Icons.load("icons/folder-open.svg").unwrap().is_some());
    }
}
